-- PKG_DMF0043 — 적용 후 확인 (SCM_MGR · 조회 전용)
SET PAGESIZE 200 LINESIZE 300

SELECT 'PKG_DMF0043' OBJ, 'PACKAGE' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0043' AND OBJECT_TYPE = 'PACKAGE') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_DMF0043' AND TYPE = 'PACKAGE' AND LINE > 1) = 277371583227 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT 'PKG_DMF0043' OBJ, 'PACKAGE BODY' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0043' AND OBJECT_TYPE = 'PACKAGE BODY') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'PKG_DMF0043' AND TYPE = 'PACKAGE BODY' AND LINE > 1) = 6675452987132 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT 'DMF0043_GET_MAIN_SPREAD_TITLE' OBJ, 'PROCEDURE' TYP, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'DMF0043_GET_MAIN_SPREAD_TITLE' AND OBJECT_TYPE = 'PROCEDURE') STATUS, CASE WHEN (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) FROM USER_SOURCE WHERE NAME = 'DMF0043_GET_MAIN_SPREAD_TITLE' AND TYPE = 'PROCEDURE' AND LINE > 1) = 411502891212 THEN 'SAME(사내 적용본)' ELSE 'CHECK' END SOURCE_CHK FROM DUAL;
SELECT NAME, TYPE, LINE, POSITION, TEXT FROM USER_ERRORS WHERE NAME IN ('DMF0043_GET_MAIN_SPREAD_TITLE', 'PKG_DMF0043') ORDER BY NAME, TYPE, SEQUENCE;
SELECT OBJECT_NAME PKG, PROCEDURE_NAME MEMBER FROM USER_PROCEDURES WHERE OBJECT_NAME = 'PKG_DMF0043' AND PROCEDURE_NAME IN ('P_DMF0043_GET_CONTRIBUTE_MAIN_DATA', 'P_DMF0043_GET_CONTRIBUTE_RATE_POPUP', 'P_DMF0043_GET_CONTRIBUTE_YEAR_POPUP', 'P_DMF0043_GET_CONTRIBUTION_SALES_LIST', 'P_DMF0043_GET_CONT_VIEW_VERSIONPOPUP', 'P_DMF0043_GET_MAIN_SPREAD_TITLE', 'P_DMF0043_GET_MAIN_VARSION_DATA', 'P_DMF0043_GET_SALES_LIST_SPREAD_TITLE', 'P_DMF0043_SAVE_DM_MST_CONTRIBUTE_RATIO', 'P_DMF0043_SAVE_DM_MST_CONTRIBUTE_VER') ORDER BY 2;  -- 기대 10행
SELECT OBJECT_NAME, OBJECT_TYPE FROM USER_OBJECTS WHERE STATUS = 'INVALID' AND OBJECT_TYPE IN ('PACKAGE','PACKAGE BODY','PROCEDURE','FUNCTION') ORDER BY 1;
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0043';
